    · exact Summable.add ( by tauto ) ( by tauto );
    · exact Summable.mul_left _ ( Summable.add ( by tauto ) ( by tauto ) );
    · exact Summable.mul_left _ ( Summable.add ( by tauto ) ( by tauto ) )

